parameters.jsCode:
const rows = $input.all().map(i => i.json);
const question = $('Réception question').first().json.chatInput;

const context = rows
  .map((r, i) => `[Source ${i + 1} — ${r.title} (${r.category})]\n${r.content}`)
  .join('\n\n');

const sources = [...new Set(rows.map(r => r.title))];

return [{ json: { question, context, sources } }];

