const answer = $json.content?.[0]?.text || "Désolé, je n'ai pas pu générer de réponse.";
const sources = $('Construire le contexte').first().json.sources || [];
const footer = sources.length ? `\n\nSources : ${sources.join(', ')}` : '';

return [{ json: { output: answer + footer } }];
